// Golden values of the Portfolio schedule (docs/spec/05 §3). The oracle is the prototype itself: pfplan.golden.json
// holds its render values (EN `renderValsEN`, FR `renderVals`) for every zone, generated by
// scripts/proto-golden-pfplan.ts (prototype logic 3096–5239 evaluated in node:vm). The inputs are rebuilt here from
// the prototype data set (initialProjects, STAGE_HISTORY, PIPE_PLAN, projectData) the way the DAL resolves them, so
// this test checks the pure model; src/features/pfplan/pfplan.render.test.ts checks the same values on the database.
// L-8 (R-136): the screen's window slides (default Oct 2025 – Sep 2027 on the seed); every comparison with the
// prototype pins the window to its fixed Jan 2026 – Dec 2027 (`from: 0`). The sliding window is tested in
// pfplan-window.test.ts.
import { describe, expect, it } from 'vitest';
import { makeT, type Lang } from '@/i18n/translate';
import { mIdx } from '@/lib/format';
import { stage as stageCodec, type PipelineWindow } from '@/server/db/codes';
import { PROTO, PROTO_GEN } from '@/server/prototype';
import {
  PG_FILTERS, PG_NOW, PG_TODAY_L, boardTitle, isPgFilter, pgPct, pgRow, pgSeg, portfolioScheduleModel,
  type PgInput, type PgKpiTint, type PgRow, type PgRowInput, type PgSegment, type PgTint,
} from './pfplan';
import golden from './pfplan.golden.json';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = golden as any;
const ZONES = ['null', 'euna', 'afr', 'apac'] as const;
const LANGS: Lang[] = ['en', 'fr'];

// ── Inputs from the prototype data (what the DAL stores and resolves) ─────────────────────────────────

const WIN: Record<string, PipelineWindow> = { Initiative: 'initiative', Board: 'board', APS: 'aps', APD: 'apd' };
const PIPE = ['Initiative', 'APS', 'APD'];

function inputRow(p: any): PgRowInput {
  const pipeline = PIPE.includes(p.status);
  const startM = mIdx(p.start) ?? PG_NOW;
  const fin = mIdx(p.finish);
  let plan: [string, number, number][];
  if (pipeline)
    plan = PROTO.PIPE_PLAN[p.code] ?? [
      ['Initiative', startM - 3, startM - 2.2], ['Board', startM - 2.2, startM - 1.6], ['APS', startM - 1.6, startM - 0.8],
      ['Board', startM - 0.8, startM - 0.4], ['APD', startM - 0.4, startM + 0.3], ['Board', startM + 0.3, startM + 0.6],
    ];
  else {
    const hist: any[] = PROTO.STAGE_HISTORY[p.code] ?? [];
    const hm = (st: string) => {
      const h = hist.find((x) => x[0] === st);
      return h ? mIdx(h[1]) : null;
    };
    const i0 = hm('Initiative') ?? startM, a0 = hm('APS') ?? i0 + 1, d0 = hm('APD') ?? a0 + 1.1, e0 = hm('Etudes') ?? d0 + 1.2;
    plan = [['Initiative', i0, a0 - 0.25], ['Board', a0 - 0.25, a0], ['APS', a0, d0 - 0.25], ['Board', d0 - 0.25, d0], ['APD', d0, e0 - 0.3], ['Board', e0 - 0.3, e0]];
  }
  const pd = PROTO_GEN.projectData[p.code];
  return {
    project: {
      code: p.code, displayId: PROTO.PROJ_ID[p.code]?.id ?? p.code, name: p.name, pm: p.pm, client: p.client, status: p.status,
      stage: stageCodec.code(p.status), finish: p.finish, budget: p.budget, actual: p.actual, progress: p.progress, spi: p.spi ?? null,
      hasData: !!PROTO.DEFS[p.code],
    },
    pipeline,
    finishMonth: fin === null ? null : fin + 1,
    windows: plan.map(([w, start, end]) => ({ window: WIN[w], start, end })),
    execStart: plan[plan.length - 1][2],
    schedule: pd
      ? {
          start: pd.start, floatDays: pd.floatDays, finishText: pd.finishText, baselineText: pd.baselineText,
          milestones: pd.MILES.map(([name, , fc, st]: any[]) => ({ name, forecastMonth: fc, statusLabel: st })),
        }
      : null,
  };
}

const LIVE = PROTO_GEN.initialProjects.filter((p) => !['Clos', 'Annulé'].includes(p.status));
const boardWaits = Object.values(PROTO.PIPE_PLAN as Record<string, [string, number, number][]>).flatMap((pl) =>
  pl.filter(([st, , b]) => st === 'Board' && b <= PG_NOW).map(([, a, b]) => (b - a) * 30),
);
const AVG_WAIT = Math.round(boardWaits.reduce((a, b) => a + b, 0) / boardWaits.length);

/** Rows of a zone: the live projects the prototype lists in that zone, register order. */
function zoneInput(zone: string): PgInput {
  const codes = new Set<string>(G.en.zones[zone].groups.flatMap((g: any) => g.codes));
  return { rows: LIVE.filter((p) => codes.has(p.code)).map(inputRow), averageBoardWaitDays: AVG_WAIT };
}

// ── Prototype render values rebuilt from the model (styles transcribed from logic 4540–4545) ─────────────

const TINT: Record<PgTint, string> = { lo: 'var(--color-accent-300)', n400: 'var(--color-neutral-400)' };
const KPI_TINT: Record<PgKpiTint, string> = { ok: 'var(--color-text)', n200: 'var(--color-neutral-200)', lo: 'var(--color-accent-300)' };
const TAG: Record<string, string> = { accent: 'tag tag-accent', outline: 'tag tag-outline', neutral: 'tag tag-neutral' };
const HATCH = 'repeating-linear-gradient(135deg, var(--color-neutral-600) 0 2px, transparent 2px 6px)';

function protoSeg(s: PgSegment, t: (x: string) => string) {
  if (s.kind === 'diamond')
    return {
      left: s.left, width: '0', top: '15px', height: '0', diamond: true,
      dBg: s.state === 'approved' ? 'var(--color-accent-300)' : s.state === 'pending' ? 'var(--color-accent)' : 'transparent',
      dBorder: s.state === 'planned' ? 'var(--color-neutral-500)' : 'transparent',
      glow: s.state === 'pending' ? '0 0 10px color-mix(in srgb, var(--color-accent) 60%, transparent)' : 'none', title: t(s.title),
    };
  const isB = s.kind === 'board';
  const done = isB ? s.state === 'approved' : s.done;
  return {
    left: s.left, width: s.width, top: isB ? '15px' : '14px', height: isB ? '12px' : '14px', radius: isB ? '2px' : '4px',
    bg: isB ? HATCH : done ? 'var(--color-neutral-600)' : 'var(--color-neutral-700)',
    border: isB ? '1px dashed ' + (s.state === 'pending' ? 'var(--color-accent)' : 'var(--color-neutral-600)') : '0',
    label: isB ? '' : t(s.label), labelColor: done ? 'var(--color-neutral-200)' : 'var(--color-neutral-300)', title: t(s.title),
    glow: isB && s.state === 'pending' ? '0 0 10px color-mix(in srgb, var(--color-accent) 45%, transparent)' : 'none',
  };
}

function protoRow(r: PgRow, t: (x: string) => string) {
  return {
    code: r.code, name: t(`${r.displayId} · ${r.name}`), pm: t(r.pmLine), status: t(r.status), tagClass: TAG[r.tone], pipe: r.pipeline,
    segs: r.segments.map((s) => protoSeg(s, t)),
    hasExec: !!r.exec, exL: r.exec?.left ?? '0', exW: r.exec?.width ?? '0',
    exBg: r.pipeline ? 'transparent' : 'var(--color-accent-800)', exBorder: r.pipeline ? '1px dashed var(--color-accent-700)' : '0',
    exFill: r.pipeline ? '0%' : r.exec?.fill, exEdge: r.pipeline ? 'none' : 'inset 0 0 0 1px var(--color-accent-700)',
    hasBase: !!r.baseline, clipped: r.clipText !== '', clipText: t(r.clipText),
    gate: t(r.gate), gateSub: t(r.gateSub), gateColor: TINT[r.gateTint],
  };
}
/** The golden row without the fields that only matter when shown (baseline geometry of rows without a baseline). */
const goldenRow = (g: any) => {
  const { bL, bW, ...rest } = g;
  const segs = g.segs.map((s: any) => Object.fromEntries(Object.entries(s).filter(([k]) => k !== 'w')));
  return { ...rest, segs, ...(g.hasBase ? { bL, bW } : {}) };
};
const withBase = (r: PgRow, o: any) => (r.baseline ? { ...o, bL: r.baseline.left, bW: r.baseline.width } : o);

describe('pfplan geometry helpers', () => {
  it('pgPct clamps to the 24-month horizon with 2 decimals; today line at 30 Sep', () => {
    expect([pgPct(-2), pgPct(0), pgPct(12), pgPct(30), PG_TODAY_L]).toEqual(['0.00%', '0.00%', '50.00%', '100.00%', '37.38%']);
    expect(G.en.todayL).toBe(PG_TODAY_L);
  });
  it('pgSeg clips to [0, 24] and drops empty segments', () => {
    expect(pgSeg(-3, -1)).toBeNull();
    expect(pgSeg(25, 26)).toBeNull();
    expect(pgSeg(-1, 2)).toEqual({ left: '0.00%', width: '8.33%', w: 2 });
    expect(pgSeg(23, 26)).toEqual({ left: '95.83%', width: '4.17%', w: 1 });
  });
  it('board titles and filters', () => {
    expect(['approved', 'pending', 'planned'].map((s) => boardTitle(s as any))).toEqual(['Group board · Approved', 'Group board · Decision pending', 'Group board · Planned']);
    expect(PG_FILTERS.map((f) => f.label)).toEqual(G.en.segCtl);
    expect([isPgFilter('exec'), isPgFilter('pipe'), isPgFilter('all'), isPgFilter('x'), isPgFilter(undefined)]).toEqual([true, true, true, false, false]);
  });
});

describe.each(LANGS)('pfplan vs prototype (%s)', (lang) => {
  const t = makeT(lang);
  const g = G[lang];

  it('static labels: stage filter, month header, template keys', () => {
    expect(t('Stage')).toBe(g.stageLabel);
    expect(PG_FILTERS.map((f) => t(f.label))).toEqual(g.segCtl);
    const m = portfolioScheduleModel({ rows: [], averageBoardWaitDays: 0 }, { filter: 'all', lang, from: 0 }).months;
    expect(m.map((x) => ({ label: t(x.label), year: x.year, bl: `1px solid var(--color-neutral-${x.yearStart ? 700 : 900})` }))).toEqual(g.months);
    expect(t('Portfolio schedule — projects in progress & pipeline')).toBe(g.title);
    expect(t('No project in this zone for this view')).toBe(g.zoneEmptyText);
    const tpl = {
      k112: 'Finish', k14: 'Project', k812: 'Baseline finish', k813: 'Portfolio schedule',
      k814: 'One line per project · execution in accent, pipeline (Initiative → APS → APD) in grey, hatched while the group board decides',
      k815: 'In progress', k816: 'Pipeline', k817: 'Group decision pending', k818: 'Execution if approved', k819: 'Next decision', k820: 'Group board', k94: 'Status',
    };
    expect(Object.fromEntries(Object.entries(tpl).map(([k, v]) => [k, t(v)]))).toEqual(g.tpl);
  });

  it.each(ZONES)('zone %s: KPI tiles, groups per filter and every row', (zone) => {
    const gz = g.zones[zone];
    const input = zoneInput(zone);
    const all = portfolioScheduleModel(input, { filter: 'all', lang, from: 0 });
    expect(all.kpis.map((k) => ({ label: t(k.label), value: t(k.value), sub: t(k.sub), color: KPI_TINT[k.tint] }))).toEqual(
      gz.kpis.map((k: any) => ({ ...k, value: String(k.value) })),
    );
    expect(all.groups.map((x) => ({ key: x.key, label: t(x.label), count: x.count, codes: x.rows.map((r) => r.code) }))).toEqual(gz.groups);
    for (const f of ['all', 'exec', 'pipe'] as const)
      expect(portfolioScheduleModel(input, { filter: f, lang, from: 0 }).groups.map((x) => x.key)).toEqual(gz.filters[f]);
    expect(all.empty).toBe(input.rows.length === 0);
    const rows = all.groups.flatMap((x) => x.rows);
    expect(rows.length).toBe(gz.groups.reduce((a: number, x: any) => a + x.count, 0));
    expect(rows.length).toBeGreaterThan(0);
    for (const r of rows) expect(withBase(r, protoRow(r, t))).toEqual(goldenRow(g.rows[r.code]));
  });
});

describe('pfplan row rules', () => {
  const base = inputRow(LIVE.find((p) => p.code === 'HLT-026'));

  it('HLT-026: execution from the APD board (15.14 %), slip 27 d past the 1 Jan 2027 baseline, opens the Plan', () => {
    const r = pgRow(base);
    expect(r.exec).toEqual({ left: '15.14%', width: '38.61%', fill: '64%', ifApproved: false });
    expect(r.baseline).toEqual({ left: '15.14%', width: '34.86%' });
    expect([r.gate, r.gateSub, r.gateTint, r.target]).toEqual(['14 Jan 2027', '−27 d', 'lo', { screen: 'plan', code: 'HLT-026' }]);
  });

  it('EWA-051: board running since 21 Sep 2026 → decision pending 8 d, next stage APS, KPI lists the code', () => {
    const r = pgRow(inputRow(LIVE.find((p) => p.code === 'EWA-051')));
    expect([r.gate, r.gateSub, r.decisionPending, r.exec?.ifApproved, r.exec?.fill, r.target]).toEqual([
      'Group board → APS', 'Decision pending · 8 d', true, true, '0%', { screen: 'projects', q: 'EWA-051' },
    ]);
    expect(r.segments.filter((s) => s.kind === 'diamond').map((s) => (s as any).state)).toEqual(['pending', 'planned', 'planned']);
  });

  it('a pipeline project with every board behind it reads "—"; a board waiting 3 weeks or less is still attention', () => {
    const past = { ...base, pipeline: true, windows: [{ window: 'board' as const, start: 2, end: 3 }], execStart: 3 };
    expect([pgRow(past).gate, pgRow(past).gateSub, pgRow(past).gateTint]).toEqual(['—', '', 'n400']);
    const short = { ...past, windows: [{ window: 'board' as const, start: 8.5, end: 9.5 }], execStart: 9.5 };
    expect([pgRow(short).gateSub, pgRow(short).gateTint]).toEqual(['Decision pending · 14 d', 'lo']);
  });

  it('a project in execution without a finish: "finish not planned", bar to max(execStart + 1, PG_NOW), no baseline', () => {
    const r = pgRow({ ...base, finishMonth: null, project: { ...base.project, finish: '—' }, execStart: 3 });
    expect([r.gate, r.gateSub, r.baseline, r.exec?.width, r.clipText]).toEqual(['finish not planned', '', null, ((PG_NOW - 3) / 24 * 100).toFixed(2) + '%', '']);
  });

  it('a bar past Dec 2027 is clipped with "→ {finish}"; pipeline execution lasts 8 months when the finish is unknown', () => {
    const rbr = pgRow(inputRow(LIVE.find((p) => p.code === 'RBR-048')));
    expect([rbr.clipText, rbr.exec?.width]).toEqual(['→ Aug 2028', '41.67%']);
    const noFin = pgRow({ ...inputRow(LIVE.find((p) => p.code === 'FTU-052')), finishMonth: null });
    const seg = pgSeg(12.8, 20.8)!;
    expect(noFin.exec).toEqual({ left: seg.left, width: seg.width, fill: '0%', ifApproved: true });
  });

  it('status tag tones follow statusTag (accent in execution, outline for Garantie and the pipeline)', () => {
    const tones = LIVE.map((p) => [p.code, pgRow(inputRow(p)).tone]);
    expect(Object.fromEntries(tones)).toMatchObject({ 'HLT-026': 'accent', 'ALP-021': 'outline', 'WSA-044': 'outline', 'PRS-038': 'accent' });
  });
});
